AssistantMessageToolRequest(name='create', tool_call_id='function-call-d6a6f00c-9654-434d-9f5b-c5d1dc369915', arguments={'file_text': 'const { useState } = React;

const FAQ_DATA = [
    {
        id: 'purr',
        question: 'Why do cats purr?',
        answer: 'Cats purr for many reasons: to express happiness, to soothe themselves when stressed or in pain, and even to communicate with their kittens or humans. Recent studies suggest that the frequency of a cat\'s purr can actually help improve bone density and promote healing.'
    },
    {
        id: 'boxes',
        question: 'Why do cats like boxes?',
        answer: 'Boxes provide cats with a sense of security and safety. In the wild, cats are both predators and prey, so having a confined space where they can hide and observe their surroundings helps reduce stress and keeps them warm.'
    },
    {
        id: 'sleep',
        question: 'How long do cats sleep?',
        answer: 'On average, cats sleep for about 12 to 16 hours a day. Some cats can even sleep up to 20 hours in a 24-hour period! This is a biological trait from their ancestors, who needed to conserve energy for hunting in short, intense bursts.'
    },
    {
        id: 'whiskers',
        question: 'Why do cats have whiskers?',
        answer: 'Whiskers, or vibrissae, are highly sensitive tactile hairs. They help cats navigate in the dark, detect changes in air currents to spot nearby movement, and judge whether they can fit through tight spaces by measuring the width of the opening.'
    }
];

const FAQItem = ({ question, answer, id }) => {
    const [isOpen, setIsOpen] = useState(false);
    const contentId = `content-${id}`;

    return (
        <div className="example">
            <button
                className="faq-question"
                onClick={() => setIsOpen(!isOpen)}
                aria-expanded={isOpen}
                aria-controls={contentId}
            >
